// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value) public {
        uint256 depositsBefore = c.depositsCount();
        // Simulate a receive() by sending ether directly
        vm.deal(address(this), 1 ether);
        (bool success, ) = address(c).call{value: 1 ether}("");
        require(success, "receive failed");
        uint256 depositsAfterReceive = c.depositsCount();
        // Now call sendMoney
        vm.prank(c.owner());
        c.sendMoney(target, value);
        uint256 depositsAfter = c.depositsCount();
        // The general rule: depositsCount should never decrease from its value after receive
        assertTrue(depositsAfter >= depositsAfterReceive);
    }
}

